     1→syntax = "proto3";
     2→
     3→package spec_oracle;
     4→
     5→service SpecOracle {
     6→  // Project management
     7→  rpc CreateProject(CreateProjectRequest) returns (CreateProjectResponse);
     8→  rpc ListProjects(ListProjectsRequest) returns (ListProjectsResponse);
     9→  rpc SwitchProject(SwitchProjectRequest) returns (SwitchProjectResponse);
    10→  rpc DeleteProject(DeleteProjectRequest) returns (DeleteProjectResponse);
    11→  rpc GetCurrentProject(GetCurrentProjectRequest) returns (GetCurrentProjectResponse);
    12→  rpc ImportProject(ImportProjectRequest) returns (ImportProjectResponse);
    13→
    14→  // Node operations
    15→  rpc AddNode(AddNodeRequest) returns (AddNodeResponse);
    16→  rpc GetNode(GetNodeRequest) returns (GetNodeResponse);
    17→  rpc ListNodes(ListNodesRequest) returns (ListNodesResponse);
    18→  rpc RemoveNode(RemoveNodeRequest) returns (RemoveNodeResponse);
    19→
    20→  // Edge operations
    21→  rpc AddEdge(AddEdgeRequest) returns (AddEdgeResponse);
    22→  rpc ListEdges(ListEdgesRequest) returns (ListEdgesResponse);
    23→  rpc RemoveEdge(RemoveEdgeRequest) returns (RemoveEdgeResponse);
    24→
    25→  // Query and analysis
    26→  rpc Query(QueryRequest) returns (QueryResponse);
    27→  rpc DetectContradictions(DetectContradictionsRequest) returns (DetectContradictionsResponse);
    28→  rpc DetectOmissions(DetectOmissionsRequest) returns (DetectOmissionsResponse);
    29→  rpc DetectLayerInconsistencies(DetectLayerInconsistenciesRequest) returns (DetectLayerInconsistenciesResponse);
    30→
    31→  // Terminology resolution
    32→  rpc ResolveTerminology(ResolveTerminologyRequest) returns (ResolveTerminologyResponse);
    33→
    34→  // Layer-aware operations
    35→  rpc FilterByLayer(FilterByLayerRequest) returns (FilterByLayerResponse);
    36→  rpc FindFormalizations(FindFormalizationsRequest) returns (FindFormalizationsResponse);
    37→
    38→  // Semantic normalization
    39→  rpc FindRelatedTerms(FindRelatedTermsRequest) returns (FindRelatedTermsResponse);
    40→  rpc DetectPotentialSynonyms(DetectPotentialSynonymsRequest) returns (DetectPotentialSynonymsResponse);
    41→
    42→  // Executable contracts
    43→  rpc GenerateContractTemplate(GenerateContractTemplateRequest) returns (GenerateContractTemplateResponse);
    44→  rpc GetTestCoverage(GetTestCoverageRequest) returns (GetTestCoverageResponse);
    45→
    46→  // Graded compliance
    47→  rpc CalculateCompliance(CalculateComplianceRequest) returns (CalculateComplianceResponse);
    48→  rpc GetComplianceReport(GetComplianceReportRequest) returns (GetComplianceReportResponse);
    49→
    50→  // Temporal queries
    51→  rpc QueryAtTimestamp(QueryAtTimestampRequest) returns (QueryAtTimestampResponse);
    52→  rpc DiffTimestamps(DiffTimestampsRequest) returns (DiffTimestampsResponse);
    53→  rpc GetNodeHistory(GetNodeHistoryRequest) returns (GetNodeHistoryResponse);
    54→  rpc GetComplianceTrend(GetComplianceTrendRequest) returns (GetComplianceTrendResponse);
    55→
    56→  // Inter-universe consistency (conversation.md U, D, A, f implementation)
    57→  rpc DetectInterUniverseInconsistencies(DetectInterUniverseInconsistenciesRequest) returns (DetectInterUniverseInconsistenciesResponse);
    58→  rpc SetNodeUniverse(SetNodeUniverseRequest) returns (SetNodeUniverseResponse);
    59→
    60→  // Automatic relationship inference
    61→  rpc InferAllRelationships(InferAllRelationshipsRequest) returns (InferAllRelationshipsResponse);
    62→
    63→  // AI-powered relationship inference (cross-layer semantic matching)
    64→  rpc InferAllRelationshipsWithAi(InferAllRelationshipsWithAiRequest) returns (InferAllRelationshipsResponse);
    65→
    66→  // ==========================================
    67→  // UDA/f Model Operations (Phase 2)
    68→  // ==========================================
    69→
    70→  // Universe operations
    71→  rpc CreateUniverse(CreateUniverseRequest) returns (CreateUniverseResponse);
    72→  rpc GetUniverse(GetUniverseRequest) returns (GetUniverseResponse);
    73→  rpc ListUniverses(ListUniversesRequest) returns (ListUniversesResponse);
    74→  rpc DeleteUniverse(DeleteUniverseRequest) returns (DeleteUniverseResponse);
    75→
    76→  // Domain operations
    77→  rpc CreateDomain(CreateDomainRequest) returns (CreateDomainResponse);
    78→  rpc GetDomain(GetDomainRequest) returns (GetDomainResponse);
    79→  rpc ListDomains(ListDomainsRequest) returns (ListDomainsResponse);
    80→  rpc UpdateDomainConstraints(UpdateDomainConstraintsRequest) returns (UpdateDomainConstraintsResponse);
    81→
    82→  // AdmissibleSet operations
    83→  rpc CreateAdmissibleSet(CreateAdmissibleSetRequest) returns (CreateAdmissibleSetResponse);
    84→  rpc GetAdmissibleSet(GetAdmissibleSetRequest) returns (GetAdmissibleSetResponse);
    85→  rpc ListAdmissibleSets(ListAdmissibleSetsRequest) returns (ListAdmissibleSetsResponse);
    86→  rpc VerifyConsistency(VerifyConsistencyRequest) returns (VerifyConsistencyResponse);
    87→  rpc VerifyImplication(VerifyImplicationRequest) returns (VerifyImplicationResponse);
    88→
    89→  // Transform operations
    90→  rpc CreateTransform(CreateTransformRequest) returns (CreateTransformResponse);
    91→  rpc GetTransform(GetTransformRequest) returns (GetTransformResponse);
    92→  rpc ListTransforms(ListTransformsRequest) returns (ListTransformsResponse);
    93→  rpc VerifyTransformSoundness(VerifyTransformSoundnessRequest) returns (VerifyTransformSoundnessResponse);
    94→
    95→  // Projection operations (core reverse mapping)
    96→  rpc ConstructU0(ConstructU0Request) returns (ConstructU0Response);
    97→  rpc SyncModel(SyncModelRequest) returns (SyncModelResponse);
    98→
    99→  // Verification operations
   100→  rpc ValidateModel(ValidateModelRequest) returns (ValidateModelResponse);
   101→}
   102→
   103→// --- Node types ---
   104→
   105→message SpecNode {
   106→  string id = 1;
   107→  string content = 2;
   108→  SpecNodeKind kind = 3;
   109→  map<string, string> metadata = 4;
   110→  int64 created_at = 5;
   111→  int64 modified_at = 6;
   112→  uint32 formality_layer = 7;  // 0=natural, 1=structured, 2=formal, 3=executable
   113→}
   114→
   115→enum SpecNodeKind {
   116→  SPEC_NODE_KIND_UNSPECIFIED = 0;
   117→  ASSERTION = 1;       // A concrete claim about behavior
   118→  CONSTRAINT = 2;      // A universal constraint (invariant)
   119→  SCENARIO = 3;        // An existential requirement (a path that must exist)
   120→  DEFINITION = 4;      // A term definition
   121→  DOMAIN = 5;          // A domain boundary declaration
   122→}
   123→
   124→// --- Edge types ---
   125→
   126→message SpecEdge {
   127→  string id = 1;
   128→  string source_id = 2;
   129→  string target_id = 3;
   130→  SpecEdgeKind kind = 4;
   131→  map<string, string> metadata = 5;
   132→  int64 created_at = 6;
   133→}
   134→
   135→enum SpecEdgeKind {
   136→  SPEC_EDGE_KIND_UNSPECIFIED = 0;
   137→  REFINES = 1;         // Target refines source (is more specific)
   138→  DEPENDS_ON = 2;      // Source depends on target
   139→  CONTRADICTS = 3;     // Source contradicts target
   140→  DERIVES_FROM = 4;    // Source is derived from target
   141→  SYNONYM = 5;         // Source and target are synonymous terms
   142→  COMPOSES = 6;        // Source composes with target into a higher-level spec
   143→  FORMALIZES = 7;      // Target is a more formal version of source
   144→  TRANSFORM = 8;       // Function f: maps spec from source universe to target universe
   145→}
   146→
   147→// --- Request/Response messages ---
   148→
   149→message AddNodeRequest {
   150→  string content = 1;
   151→  SpecNodeKind kind = 2;
   152→  map<string, string> metadata = 3;
   153→}
   154→
   155→message AddNodeResponse {
   156→  SpecNode node = 1;
   157→}
   158→
   159→message GetNodeRequest {
   160→  string id = 1;
   161→}
   162→
   163→message GetNodeResponse {
   164→  SpecNode node = 1;
   165→}
   166→
   167→message ListNodesRequest {
   168→  SpecNodeKind kind_filter = 1;  // 0 = no filter
   169→}
   170→
   171→message ListNodesResponse {
   172→  repeated SpecNode nodes = 1;
   173→}
   174→
   175→message RemoveNodeRequest {
   176→  string id = 1;
   177→}
   178→
   179→message RemoveNodeResponse {}
   180→
   181→message AddEdgeRequest {
   182→  string source_id = 1;
   183→  string target_id = 2;
   184→  SpecEdgeKind kind = 3;
   185→  map<string, string> metadata = 4;
   186→}
   187→
   188→message AddEdgeResponse {
   189→  SpecEdge edge = 1;
   190→}
   191→
   192→message ListEdgesRequest {
   193→  string node_id = 1;  // empty = list all
   194→}
   195→
   196→message ListEdgesResponse {
   197→  repeated SpecEdge edges = 1;
   198→}
   199→
   200→message RemoveEdgeRequest {
   201→  string id = 1;
   202→}
   203→
   204→message RemoveEdgeResponse {}
   205→
   206→message QueryRequest {
   207→  string natural_language_query = 1;
   208→}
   209→
   210→message QueryResponse {
   211→  repeated SpecNode matching_nodes = 1;
   212→  string explanation = 2;
   213→}
   214→
   215→message DetectContradictionsRequest {}
   216→
   217→message DetectContradictionsResponse {
   218→  repeated Contradiction contradictions = 1;
   219→}
   220→
   221→message Contradiction {
   222→  SpecNode node_a = 1;
   223→  SpecNode node_b = 2;
   224→  string explanation = 3;
   225→}
   226→
   227→message DetectOmissionsRequest {}
   228→
   229→message DetectOmissionsResponse {
   230→  repeated Omission omissions = 1;
   231→}
   232→
   233→message Omission {
   234→  string description = 1;
   235→  repeated SpecNode related_nodes = 2;
   236→}
   237→
   238→message ResolveTerminologyRequest {
   239→  string term = 1;
   240→}
   241→
   242→message ResolveTerminologyResponse {
   243→  repeated SpecNode definitions = 1;
   244→  repeated string synonyms = 2;
   245→}
   246→
   247→message DetectLayerInconsistenciesRequest {}
   248→
   249→message DetectLayerInconsistenciesResponse {
   250→  repeated LayerInconsistency inconsistencies = 1;
   251→}
   252→
   253→message LayerInconsistency {
   254→  SpecNode source = 1;
   255→  SpecNode target = 2;
   256→  string explanation = 3;
   257→}
   258→
   259→message FilterByLayerRequest {
   260→  uint32 min_layer = 1;
   261→  uint32 max_layer = 2;
   262→}
   263→
   264→message FilterByLayerResponse {
   265→  repeated SpecNode nodes = 1;
   266→}
   267→
   268→message FindFormalizationsRequest {
   269→  string node_id = 1;
   270→}
   271→
   272→message FindFormalizationsResponse {
   273→  repeated SpecNode formalizations = 1;
   274→  repeated SpecNode natural_sources = 2;
   275→}
   276→
   277→message FindRelatedTermsRequest {
   278→  string term = 1;
   279→  uint32 max_results = 2;  // 0 = no limit
   280→}
   281→
   282→message FindRelatedTermsResponse {
   283→  repeated ScoredNode nodes = 1;
   284→}
   285→
   286→message ScoredNode {
   287→  SpecNode node = 1;
   288→  float score = 2;  // Similarity score 0.0-1.0
   289→}
   290→
   291→message DetectPotentialSynonymsRequest {
   292→  float min_similarity = 1;  // Minimum similarity threshold (default 0.3)
   293→}
   294→
   295→message DetectPotentialSynonymsResponse {
   296→  repeated SynonymCandidate candidates = 1;
   297→}
   298→
   299→message SynonymCandidate {
   300→  SpecNode node_a = 1;
   301→  SpecNode node_b = 2;
   302→  float similarity = 3;
   303→}
   304→
   305→message GenerateContractTemplateRequest {
   306→  string node_id = 1;
   307→  string language = 2;  // Target language: "rust", "python", etc.
   308→}
   309→
   310→message GenerateContractTemplateResponse {
   311→  string template = 1;  // Generated test template code
   312→  string node_kind = 2;  // "constraint" or "scenario"
   313→}
   314→
   315→message GetTestCoverageRequest {}
   316→
   317→message GetTestCoverageResponse {
   318→  uint32 total_testable = 1;       // Total constraints + scenarios
   319→  uint32 with_tests = 2;            // Nodes with test_file metadata
   320→  float coverage_ratio = 3;         // Ratio 0.0-1.0
   321→  repeated SpecNode nodes_with_tests = 4;
   322→  repeated SpecNode nodes_without_tests = 5;
   323→}
   324→
   325→message CalculateComplianceRequest {
   326→  string node_id = 1;   // Specification node ID
   327→  string code = 2;      // Code snippet to check compliance against
   328→}
   329→
   330→message CalculateComplianceResponse {
   331→  float score = 1;              // Overall compliance score 0.0-1.0
   332→  float keyword_overlap = 2;    // Semantic keyword similarity
   333→  float structural_match = 3;   // Structural pattern matching
   334→  string explanation = 4;       // Human-readable explanation
   335→}
   336→
   337→message GetComplianceReportRequest {}
   338→
   339→message GetComplianceReportResponse {
   340→  repeated ComplianceEntry entries = 1;
   341→}
   342→
   343→message ComplianceEntry {
   344→  SpecNode node = 1;
   345→  float score = 2;
   346→  float keyword_overlap = 3;
   347→  float structural_match = 4;
   348→  string explanation = 5;
   349→}
   350→
   351→message QueryAtTimestampRequest {
   352→  int64 timestamp = 1;  // Unix timestamp
   353→}
   354→
   355→message QueryAtTimestampResponse {
   356→  int64 timestamp = 1;
   357→  repeated SpecNode nodes = 2;
   358→  repeated SpecEdge edges = 3;
   359→  uint32 node_count = 4;
   360→  uint32 edge_count = 5;
   361→}
   362→
   363→message DiffTimestampsRequest {
   364→  int64 from_timestamp = 1;
   365→  int64 to_timestamp = 2;
   366→}
   367→
   368→message DiffTimestampsResponse {
   369→  int64 from_timestamp = 1;
   370→  int64 to_timestamp = 2;
   371→  repeated SpecNode added_nodes = 3;
   372→  repeated SpecNode removed_nodes = 4;
   373→  repeated NodeChange modified_nodes = 5;
   374→  repeated SpecEdge added_edges = 6;
   375→  repeated SpecEdge removed_edges = 7;
   376→}
   377→
   378→message NodeChange {
   379→  SpecNode from_node = 1;
   380→  SpecNode to_node = 2;
   381→}
   382→
   383→message GetNodeHistoryRequest {
   384→  string node_id = 1;
   385→}
   386→
   387→message GetNodeHistoryResponse {
   388→  SpecNode node = 1;
   389→  repeated HistoryEvent events = 2;
   390→}
   391→
   392→message HistoryEvent {
   393→  int64 timestamp = 1;
   394→  string event_type = 2;  // "created", "modified", "edge_added"
   395→  string description = 3;
   396→}
   397→
   398→message GetComplianceTrendRequest {
   399→  string node_id = 1;
   400→}
   401→
   402→message GetComplianceTrendResponse {
   403→  SpecNode node = 1;
   404→  repeated ComplianceDataPoint data_points = 2;
   405→  string trend_direction = 3;  // "improving", "degrading", "stable", "unknown"
   406→}
   407→
   408→message ComplianceDataPoint {
   409→  int64 timestamp = 1;
   410→  float score = 2;
   411→}
   412→
   413→message DetectInterUniverseInconsistenciesRequest {}
   414→
   415→message DetectInterUniverseInconsistenciesResponse {
   416→  repeated InterUniverseInconsistency inconsistencies = 1;
   417→}
   418→
   419→message InterUniverseInconsistency {
   420→  string universe_a = 1;
   421→  string universe_b = 2;
   422→  SpecNode spec_a = 3;
   423→  SpecNode spec_b = 4;
   424→  repeated string transform_path = 5;  // Edge IDs forming transformation path
   425→  string explanation = 6;
   426→}
   427→
   428→message SetNodeUniverseRequest {
   429→  string node_id = 1;
   430→  string universe = 2;  // Universe identifier (e.g., "ui", "api", "database")
   431→}
   432→
   433→message SetNodeUniverseResponse {
   434→  SpecNode node = 1;
   435→}
   436→
   437→message InferAllRelationshipsRequest {}
   438→
   439→message InferAllRelationshipsWithAiRequest {
   440→  float min_confidence = 1;  // Minimum confidence threshold (0.0-1.0)
   441→}
   442→
   443→message InferAllRelationshipsResponse {
   444→  uint32 edges_created = 1;
   445→  uint32 suggestions_count = 2;
   446→  repeated string suggestions = 3;  // Human-readable edge suggestions
   447→}
   448→
   449→// ==========================================
   450→// Project Management (Phase 1)
   451→// ==========================================
   452→
   453→message CreateProjectRequest {
   454→  string name = 1;
   455→  string description = 2;
   456→  StorageBackend storage_backend = 3;  // Optional, defaults to local file
   457→}
   458→
   459→message CreateProjectResponse {
   460→  Project project = 1;
   461→}
   462→
   463→message ListProjectsRequest {}
   464→
   465→message ListProjectsResponse {
   466→  repeated Project projects = 1;
   467→}
   468→
   469→message SwitchProjectRequest {
   470→  string name = 1;
   471→}
   472→
   473→message SwitchProjectResponse {
   474→  Project project = 1;
   475→}
   476→
   477→message DeleteProjectRequest {
   478→  string name = 1;
   479→}
   480→
   481→message DeleteProjectResponse {}
   482→
   483→message GetCurrentProjectRequest {}
   484→
   485→message GetCurrentProjectResponse {
   486→  Project project = 1;
   487→}
   488→
   489→message ImportProjectRequest {
   490→  string name = 1;              // Project name to create
   491→  string description = 2;       // Project description
   492→  string spec_directory_path = 3;  // Path to legacy .spec/ directory
   493→}
   494→
   495→message ImportProjectResponse {
   496→  Project project = 1;
   497→  uint32 nodes_imported = 2;
   498→  uint32 edges_imported = 3;
   499→  uint32 universes_created = 4;
   500→}
   501→
   502→message Project {
   503→  string name = 1;
   504→  string description = 2;
   505→  int64 created_at = 3;
   506→  uint32 node_count = 4;
   507→  uint32 edge_count = 5;
   508→  StorageBackend storage = 6;
   509→}
   510→
   511→enum StorageBackend {
   512→  STORAGE_BACKEND_UNSPECIFIED = 0;
   513→  LOCAL_FILE = 1;
   514→  DATABASE = 2;
   515→  S3 = 3;
   516→  GIT = 4;
   517→}
   518→
   519→// ==========================================
   520→// UDA/f Model Types (Phase 2)
   521→// ==========================================
   522→
   523→// Universe: The space in which specifications are defined (U0, U1, ...)
   524→message UdafUniverse {
   525→  string id = 1;              // e.g., "U0", "U1", "U2"
   526→  string name = 2;            // Human-readable name
   527→  string description = 3;     // What this universe represents
   528→  uint32 layer = 4;           // Layer number (0=root, 1=formal, 2=interface, 3=impl)
   529→  repeated string spec_ids = 5; // Specification IDs in this universe
   530→  map<string, string> metadata = 6;
   531→}
   532→
   533→// Domain: The region a specification covers
   534→message UdafDomain {
   535→  string id = 1;              // UUID
   536→  string name = 2;            // Human-readable name
   537→  string description = 3;     // What this domain covers
   538→  string universe_id = 4;     // Which universe this domain belongs to
   539→  repeated UdafConstraint constraints = 5;  // Domain boundary constraints
   540→  repeated string covered_by = 6;  // Spec IDs that cover this domain
   541→  repeated string subdomain_ids = 7; // Child domain IDs
   542→  map<string, string> metadata = 8;
   543→}
   544→
   545→// AdmissibleSet: The set of allowed implementations for a specification
   546→message UdafAdmissibleSet {
   547→  string spec_id = 1;         // Specification ID (UUID)
   548→  string universe_id = 2;     // Which universe this belongs to
   549→  repeated UdafConstraint constraints = 3;  // Constraints defining membership
   550→  repeated string contradicts = 4;  // Spec IDs this contradicts
   551→  map<string, string> metadata = 5;
   552→}
   553→
   554→// Constraint: A symbolic membership condition
   555→message UdafConstraint {
   556→  string formal = 1;          // Formal representation (e.g., ">= 8")
   557→  UdafConstraintKind kind = 2;
   558→  string description = 3;     // Natural language description
   559→  map<string, string> metadata = 4;
   560→}
   561→
   562→enum UdafConstraintKind {
   563→  UDAF_CONSTRAINT_KIND_UNSPECIFIED = 0;
   564→  UNIVERSAL = 1;     // Must hold for all cases
   565→  EXISTENTIAL = 2;   // Must hold for at least one case
   566→  IMPLICATION = 3;   // If condition then consequence
   567→  EQUIVALENCE = 4;   // Bidirectional implication
   568→}
   569→
   570→// Transform: Mapping between universes
   571→message UdafTransform {
   572→  string id = 1;              // e.g., "f_U1_to_U0"
   573→  string source_universe = 2; // Source universe ID
   574→  string target_universe = 3; // Target universe ID
   575→  string description = 4;     // Human-readable description
   576→  UdafTransformKind kind = 5;
   577→  UdafTransformStrategy strategy = 6;
   578→  map<string, string> metadata = 7;
   579→}
   580→
   581→enum UdafTransformKind {
   582→  UDAF_TRANSFORM_KIND_UNSPECIFIED = 0;
   583→  FORWARD = 1;       // Ui -> Uj (more concrete)
   584→  INVERSE = 2;       // Ui -> U0 (reverse mapping to root)
   585→  PARALLEL = 3;      // Ui -> Uj (different aspects, same layer)
   586→}
   587→
   588→message UdafTransformStrategy {
   589→  string strategy_type = 1;   // "ast_analysis", "nlp_inference", "formal_verification", "type_analysis", "manual"
   590→  map<string, string> config = 2;  // Strategy-specific configuration
   591→}
   592→
   593→// Proof result from verification operations
   594→message UdafProofResult {
   595→  string id = 1;
   596→  UdafProofStatus status = 2;
   597→  string property_type = 3;   // "consistency", "satisfiability", "implication", "completeness", "soundness"
   598→  repeated UdafProofStep steps = 4;
   599→  string method = 5;          // "constraint_solving", "smt_solver", "heuristic"
   600→  map<string, string> metadata = 6;
   601→}
   602→
   603→enum UdafProofStatus {
   604→  UDAF_PROOF_STATUS_UNSPECIFIED = 0;
   605→  PROVEN = 1;        // Property is proven true
   606→  REFUTED = 2;       // Property is proven false
   607→  UNKNOWN = 3;       // Unable to prove or refute
   608→  PENDING = 4;       // Proof attempt in progress
   609→}
   610→
   611→message UdafProofStep {
   612→  string description = 1;
   613→  string justification = 2;
   614→}
   615→
   616→// ==========================================
   617→// UDA/f Request/Response Messages (Phase 2)
   618→// ==========================================
   619→
   620→// --- Universe operations ---
   621→
   622→message CreateUniverseRequest {
   623→  uint32 layer = 1;           // Layer number (1-255, 0 is reserved for U0)
   624→  string name = 2;
   625→  string description = 3;
   626→}
   627→
   628→message CreateUniverseResponse {
   629→  UdafUniverse universe = 1;
   630→}
   631→
   632→message GetUniverseRequest {
   633→  string id = 1;              // e.g., "U0", "U1"
   634→}
   635→
   636→message GetUniverseResponse {
   637→  UdafUniverse universe = 1;
   638→}
   639→
   640→message ListUniversesRequest {}
   641→
   642→message ListUniversesResponse {
   643→  repeated UdafUniverse universes = 1;
   644→}
   645→
   646→message DeleteUniverseRequest {
   647→  string id = 1;
   648→}
   649→
   650→message DeleteUniverseResponse {}
   651→
   652→// --- Domain operations ---
   653→
   654→message CreateDomainRequest {
   655→  string name = 1;
   656→  string description = 2;
   657→  string universe_id = 3;     // Which universe this domain belongs to
   658→}
   659→
   660→message CreateDomainResponse {
   661→  UdafDomain domain = 1;
   662→}
   663→
   664→message GetDomainRequest {
   665→  string id = 1;              // Domain UUID
   666→}
   667→
   668→message GetDomainResponse {
   669→  UdafDomain domain = 1;
   670→}
