                    node_id: id.clone(),
                    universe: universe.clone(),
                }))
                .await?;
            if let Some(node) = resp.into_inner().node {
                println!("Set universe for [{}]: {}", &node.id[..8.min(node.id.len())], universe);
            }
        }
        RpcCommands::FilterByLayer { min, max } => {
            let resp = client
