use crate::project::{ProjectManager, Project};
use crate::proto;
use crate::model_service::ModelServiceImpl;
use spec_core::data::{EdgeKind, NodeKind, SpecRepository};
use std::sync::{Arc, Mutex};
use tonic::{Request, Response, Status};

pub struct SpecOracleService {
    project_manager: Arc<Mutex<ProjectManager>>,
    model_svc: ModelServiceImpl,
}

impl SpecOracleService {
    pub fn new(project_manager: ProjectManager) -> Result<Self, Box<dyn std::error::Error>> {
        let pm = Arc::new(Mutex::new(project_manager));
        let model_svc = ModelServiceImpl::new(pm.clone());
        Ok(Self {
            project_manager: pm,
            model_svc,
        })
    }

    /// Get the current project or use the specified project name
    fn get_project(&self, project_name: &str) -> Result<Project, Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        let name = if project_name.is_empty() {
            pm.current_project()
                .ok_or_else(|| Status::failed_precondition("No current project set. Use SwitchProject or specify project name."))?
        } else {
            project_name.to_string()
        };

        pm.load_project(&name)
            .map_err(|e| Status::not_found(format!("Project not found: {}", e)))
    }

    /// Save a project back to storage
    fn save_project(&self, project: &Project) -> Result<(), Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        pm.save_project(project)
            .map_err(|e| Status::internal(format!("Failed to save project: {}", e)))
    }

    /// Add node with explicit formality layer (helper method)
    fn add_node_with_layer(
        repo: &mut SpecRepository,
        content: String,
        kind: NodeKind,
        formality_layer: u8,
        metadata: std::collections::HashMap<String, String>,
    ) -> spec_core::data::SpecNodeData {
        let node = repo.add_node(content, kind, metadata).clone();
        let node_id = node.id.clone();
        repo.update_node_formality(&node_id, formality_layer);
        repo.get_node(&node_id).unwrap().clone()
    }
}

// ==========================================
// Proto conversion helpers
// ==========================================

fn to_proto_node(n: &spec_core::data::SpecNodeData) -> proto::SpecNode {
    proto::SpecNode {
        id: n.id.clone(),
        content: n.content.clone(),
        kind: to_proto_node_kind(n.kind).into(),
        metadata: n.metadata.clone(),
        created_at: n.created_at,
        modified_at: n.modified_at,
        formality_layer: n.formality_layer as u32,
    }
}

fn to_proto_node_kind(k: NodeKind) -> proto::SpecNodeKind {
    match k {
        NodeKind::Assertion => proto::SpecNodeKind::Assertion,
        NodeKind::Constraint => proto::SpecNodeKind::Constraint,
        NodeKind::Scenario => proto::SpecNodeKind::Scenario,
        NodeKind::Definition => proto::SpecNodeKind::Definition,
        NodeKind::Domain => proto::SpecNodeKind::Domain,
    }
}

fn from_proto_node_kind(k: i32) -> NodeKind {
    match proto::SpecNodeKind::try_from(k) {
        Ok(proto::SpecNodeKind::Assertion) => NodeKind::Assertion,
        Ok(proto::SpecNodeKind::Constraint) => NodeKind::Constraint,
        Ok(proto::SpecNodeKind::Scenario) => NodeKind::Scenario,
        Ok(proto::SpecNodeKind::Definition) => NodeKind::Definition,
        Ok(proto::SpecNodeKind::Domain) => NodeKind::Domain,
        _ => NodeKind::Assertion,
    }
}

