/// Summary command: Display specification statistics (gRPC only)

use crate::proto;
use crate::utils::node_kind_name;
use crate::presentation::formatter::format_formality_layer;
use std::collections::HashMap;
use tonic::Request;

/// Execute the Summary command via gRPC
pub async fn execute_summary_server(
    client: &mut proto::spec_oracle_client::SpecOracleClient<tonic::transport::Channel>,
) -> Result<(), Box<dyn std::error::Error>> {
    // Get all nodes
    let nodes_resp = client
        .list_nodes(Request::new(proto::ListNodesRequest { kind_filter: 0 }))
        .await?;
    let nodes = nodes_resp.into_inner().nodes;

    // Get all edges
    let edges_resp = client
        .list_edges(Request::new(proto::ListEdgesRequest { node_id: String::new() }))
        .await?;
    let edges = edges_resp.into_inner().edges;

    // Count by kind
    let mut by_kind = HashMap::<String, usize>::new();
    for node in &nodes {
        let kind_str = node_kind_name(node.kind).to_string();
        *by_kind.entry(kind_str).or_insert(0) += 1;
    }

    // Count by layer
    let mut by_layer = HashMap::<u32, usize>::new();
    for node in &nodes {
        *by_layer.entry(node.formality_layer).or_insert(0) += 1;
    }

    // Run checks
    let contra_resp = client
        .detect_contradictions(Request::new(proto::DetectContradictionsRequest {}))
        .await?;
    let contradictions = contra_resp.into_inner().contradictions;

    let omit_resp = client
        .detect_omissions(Request::new(proto::DetectOmissionsRequest {}))
        .await?;
    let omissions = omit_resp.into_inner().omissions;

    // Display summary
    println!("Specification Summary\n");
    println!("Total Specifications: {}", nodes.len());
    println!();

    println!("By Kind:");
    let mut kind_vec: Vec<_> = by_kind.iter().collect();
    kind_vec.sort_by_key(|(k, _)| k.as_str());
    for (kind, count) in &kind_vec {
        println!("  {}: {}", kind, count);
    }
    println!();

    println!("By Formality Layer:");
    let mut sorted_layers: Vec<_> = by_layer.iter().collect();
    sorted_layers.sort_by_key(|(k, _)| *k);
    for (layer, count) in sorted_layers {
        let label = format_formality_layer(*layer as u8);
        println!("  {}: {}", label, count);
    }
    println!();

    println!("Relationships: {} edges", edges.len());
    println!();

    println!("Health:");
    if contradictions.is_empty() {
        println!("  No contradictions");
    } else {
        println!("  {} contradiction(s)", contradictions.len());
    }
    if omissions.is_empty() {
        println!("  No isolated specs");
    } else {
        println!("  {} isolated spec(s)", omissions.len());
    }

    if contradictions.is_empty() && omissions.is_empty() {
        println!("\nSpecifications are healthy!");
    } else if !contradictions.is_empty() {
        println!("\nCritical issues found. Run 'spec check' for details.");
    } else {
        println!("\nMinor issues. Run 'spec check' for details.");
    }

    Ok(())
}

