RpcCommands::ListNodes { kind, layer, status, full, limit, offset } => {
    eprintln!("⚠️  WARNING: 'spec rpc list-nodes' is deprecated.");
    eprintln!("   Use 'spec rpc list-admissible-sets' or 'spec summary' instead.");
    eprintln!("   This command will be removed in a future version.\n");

    let kind_filter = kind.as_ref().map(|k| parse_node_kind(k));
    let resp = client
        .list_nodes(Request::new(proto::ListNodesRequest {
            kind_filter: kind_filter.map(|k| k.into()).unwrap_or(0),
        }))
        .await?;
    let mut nodes = resp.into_inner().nodes;

    // Apply layer filter
    if let Some(layer_filter) = layer {
        nodes.retain(|n| n.formality_layer == layer_filter as u32);
    }

    // Apply status filter
    if let Some(ref status_filter) = status {
        nodes.retain(|n| {
            let node_status = n.metadata.get("status")
                .map(|s| s.as_str())
                .unwrap_or("active");
            node_status == status_filter.as_str()
        });
    }

    if !full {
        println!("Specification Summary");
        println!("Total: {} specifications", nodes.len());
        println!();

        let mut by_layer = HashMap::<u32, usize>::new();
        for node in &nodes {
            *by_layer.entry(node.formality_layer).or_insert(0) += 1;
        }

        println!("By Formality Layer:");
        for layer_num in 0..=3 {
            if let Some(&count) = by_layer.get(&layer_num) {
                let layer_label = format_formality_layer(layer_num as u8);
                println!("  {}: {} specs", layer_label, count);
            }
        }
        println!();

        let mut by_kind = HashMap::<String, usize>::new();
        for node in &nodes {
            let kind_str = node_kind_name(node.kind).to_string();
            *by_kind.entry(kind_str).or_insert(0) += 1;
        }

        println!("By Kind:");
        let mut kind_vec: Vec<_> = by_kind.iter().collect();
        kind_vec.sort_by_key(|(k, _)| k.as_str());
        for (kind, count) in kind_vec {
            println!("  {}: {}", kind, count);
        }
        println!();
        println!("Use --full to see the complete list");
    } else {
        let offset_val = offset.unwrap_or(0);
        let limit_val = limit.unwrap_or(nodes.len());
        let end = std::cmp::min(offset_val + limit_val, nodes.len());
        let page_nodes: Vec<_> = nodes.iter().skip(offset_val).take(limit_val).collect();

        println!("Found {} node(s):", nodes.len());
        if offset_val > 0 || limit.is_some() {
            println!("Showing {} - {} of {}:", offset_val + 1, end, nodes.len());
        }
        println!();

        for node in page_nodes {
            let layer_label = format_formality_layer(node.formality_layer as u8);
            let id_short = &node.id[..8.min(node.id.len())];
            println!("  [{}] [{}] {} - {}",
                layer_label,
                id_short,
                node_kind_name(node.kind),
                node.content.chars().take(80).collect::<String>());
        }

        if end < nodes.len() {
            println!();
            println!("... and {} more (use --offset {} to see next page)", nodes.len() - end, end);
        }
    }
}
