/// Export DOT format command (gRPC only)

use crate::proto;
use crate::utils::{node_kind_name, edge_kind_name};
use tonic::Request;
use std::fs::File;
use std::io::Write;

/// Execute Export DOT command via gRPC
pub async fn execute_export_dot_server(
    client: &mut proto::spec_oracle_client::SpecOracleClient<tonic::transport::Channel>,
    output: Option<String>,
    layer: Option<u32>,
    metadata: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    // Get all nodes
    let nodes_resp = client
        .list_nodes(Request::new(proto::ListNodesRequest { kind_filter: 0 }))
        .await?;
    let nodes = nodes_resp.into_inner().nodes;

    // Get all edges
    let edges_resp = client
        .list_edges(Request::new(proto::ListEdgesRequest { node_id: String::new() }))
        .await?;
    let edges = edges_resp.into_inner().edges;

    // Start building DOT graph
    let mut dot = String::new();
    dot.push_str("digraph specifications {\n");
    dot.push_str("  rankdir=LR;\n");
    dot.push_str("  node [shape=box];\n\n");

    // Add nodes
    for node in &nodes {
        // Skip nodes not in the specified layer if filter is set
        if let Some(filter_layer) = layer {
            if node.formality_layer != filter_layer {
                continue;
            }
        }

        let id_short = &node.id[..8.min(node.id.len())];
        let mut label = format!("{}\n{}", id_short, node_kind_name(node.kind));

        if metadata && !node.metadata.is_empty() {
            label.push_str("\n");
            for (key, value) in &node.metadata {
                label.push_str(&format!("{}: {}\n", key, value));
            }
        }

        // Escape quotes in content
        let content_escaped = node.content.replace("\"", "\\\"");
        label.push_str(&format!("\n{}", content_escaped));

        // Color by layer
        let color = match node.formality_layer {
            0 => "lightblue",   // Natural language
            1 => "lightgreen",  // Structured
            2 => "lightyellow", // Formal
            3 => "lightpink",   // Executable
            _ => "white",
        };

        dot.push_str(&format!(
            "  \"{}\" [label=\"{}\", style=filled, fillcolor={}];\n",
            node.id, label, color
        ));
    }

    dot.push_str("\n");

    // Add edges
    for edge in &edges {
        // Skip edges if both nodes are filtered out
        if let Some(filter_layer) = layer {
            let source_node = nodes.iter().find(|n| n.id == edge.source_id);
            let source_in_layer = source_node.map(|n| n.formality_layer == filter_layer).unwrap_or(false);

            let target_node = nodes.iter().find(|n| n.id == edge.target_id);
            let target_in_layer = target_node.map(|n| n.formality_layer == filter_layer).unwrap_or(false);

            if !source_in_layer || !target_in_layer {
                continue;
            }
        }

        let label = edge_kind_name(edge.kind);
        dot.push_str(&format!(
            "  \"{}\" -> \"{}\" [label=\"{}\"];\n",
            edge.source_id, edge.target_id, label
        ));
    }

    dot.push_str("}\n");

    // Write to output
    if let Some(path) = output {
        let mut file = File::create(&path)?;
        file.write_all(dot.as_bytes())?;
        println!("DOT graph exported to: {}", path);
    } else {
        println!("{}", dot);
    }

    Ok(())
}

