/// Export DOT format command using UDA/f operations (gRPC only)

use crate::proto;
use tonic::Request;
use std::fs::File;
use std::io::Write;

/// Execute Export DOT command via gRPC using UDA/f operations
pub async fn execute_export_dot_server(
    client: &mut proto::spec_oracle_client::SpecOracleClient<tonic::transport::Channel>,
    output: Option<String>,
    layer: Option<u32>,
    _metadata: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    // Get all universes
    let universes_resp = client
        .list_universes(Request::new(proto::ListUniversesRequest {}))
        .await?;
    let universes = universes_resp.into_inner().universes;

    // Get all admissible sets
    let sets_resp = client
        .list_admissible_sets(Request::new(proto::ListAdmissibleSetsRequest {
            universe_id: String::new(),
        }))
        .await?;
    let admissible_sets = sets_resp.into_inner().admissible_sets;

    // Get all transforms
    let transforms_resp = client
        .list_transforms(Request::new(proto::ListTransformsRequest {
            universe_id: String::new(),
        }))
        .await?;
    let transforms = transforms_resp.into_inner().transforms;

    // Start building DOT graph
    let mut dot = String::new();
    dot.push_str("digraph specifications {\n");
    dot.push_str("  rankdir=LR;\n");
    dot.push_str("  node [shape=box];\n\n");

    // Add universes as clusters
    dot.push_str("  // Universes\n");
    for universe in &universes {
        // Skip if layer filter is set and doesn't match
        if let Some(filter_layer) = layer {
            if universe.layer != filter_layer {
                continue;
            }
        }

        let color = match universe.layer {
            0 => "lightblue",   // U0: Natural language
            1 => "lightgreen",  // U1: Formal specs
            2 => "lightyellow", // U2: Interface
            3 => "lightpink",   // U3: Implementation
            _ => "white",
        };

        dot.push_str(&format!(
            "  \"{}\" [label=\"{}\n{}\", style=filled, fillcolor={}];\n",
            universe.id, universe.id, universe.name, color
        ));
    }

    dot.push_str("\n  // Admissible Sets\n");
    // Add admissible sets as nodes
    for set in &admissible_sets {
        // Filter by universe layer if specified
        if let Some(filter_layer) = layer {
            let universe = universes.iter().find(|u| u.id == set.universe_id);
            if let Some(u) = universe {
                if u.layer != filter_layer {
                    continue;
                }
            }
        }

        let id_short = &set.spec_id[..8.min(set.spec_id.len())];
        let constraints_summary = if set.constraints.is_empty() {
            "No constraints".to_string()
        } else {
            set.constraints[0].description.chars().take(40).collect::<String>()
        };

        dot.push_str(&format!(
            "  \"{}\" [label=\"Spec {}\n{}\", shape=ellipse];\n",
            set.spec_id, id_short, constraints_summary
        ));

        // Connect spec to its universe
        dot.push_str(&format!(
            "  \"{}\" -> \"{}\" [style=dashed, color=gray, label=\"in\"];\n",
            set.spec_id, set.universe_id
        ));
    }

    dot.push_str("\n  // Transforms\n");
    // Add transforms as edges
    for transform in &transforms {
        // Filter by layer if specified
        if let Some(filter_layer) = layer {
            let source_universe = universes.iter().find(|u| u.id == transform.source_universe);
            let target_universe = universes.iter().find(|u| u.id == transform.target_universe);

            let source_matches = source_universe.map(|u| u.layer == filter_layer).unwrap_or(false);
            let target_matches = target_universe.map(|u| u.layer == filter_layer).unwrap_or(false);

            if !source_matches || !target_matches {
                continue;
            }
        }

        let kind = match transform.kind {
            1 => "FORWARD",
            2 => "INVERSE",
            3 => "PARALLEL",
            _ => "UNKNOWN",
        };

        let color = match transform.kind {
            1 => "blue",    // Forward
            2 => "red",     // Inverse
            3 => "green",   // Parallel
            _ => "black",
        };

        dot.push_str(&format!(
            "  \"{}\" -> \"{}\" [label=\"{}\" color={}];\n",
            transform.source_universe, transform.target_universe, kind, color
        ));
    }

    dot.push_str("}\n");

    // Write to output
    if let Some(path) = output {
        let mut file = File::create(&path)?;
        file.write_all(dot.as_bytes())?;
        println!("DOT graph exported to: {}", path);
        println!("  Universes: {}", universes.len());
        println!("  Specifications: {}", admissible_sets.len());
        println!("  Transforms: {}", transforms.len());
    } else {
        println!("{}", dot);
    }

    Ok(())
}

