/// Export command: Generate DOT format for Graphviz visualization (gRPC only)

use crate::proto::{self, spec_oracle_client::SpecOracleClient};
use crate::utils::{node_kind_name, edge_kind_name};
use tonic::Request;

/// Execute the export-dot command via gRPC
pub async fn execute_export_dot_server(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    output_file: Option<String>,
    layer: Option<u32>,
    include_metadata: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    // Fetch all nodes
    let nodes_resp = client
        .list_nodes(Request::new(proto::ListNodesRequest { kind_filter: 0 }))
        .await?;
    let nodes = nodes_resp.into_inner().nodes;

    // Fetch all edges
    let edges_resp = client
        .list_edges(Request::new(proto::ListEdgesRequest { node_id: String::new() }))
        .await?;
    let edges = edges_resp.into_inner().edges;

    // Build DOT format output
    let mut dot = String::new();
    dot.push_str("digraph SpecificationGraph {\n");
    dot.push_str("  rankdir=TB;\n");
    dot.push_str("  node [shape=box, style=rounded];\n");
    dot.push_str("  edge [fontsize=10];\n\n");

    // Add subgraphs for each layer
    for l in 0u32..=3u32 {
        // Skip if layer filter is set and doesn't match
        if let Some(filter_layer) = layer {
            if filter_layer != l {
                continue;
            }
        }

        dot.push_str(&format!("  subgraph cluster_U{} {{\n", l));
        dot.push_str(&format!("    label=\"U{}: {}\";\n", l, layer_name(l)));
        dot.push_str("    color=lightgray;\n");
        dot.push_str("    style=filled;\n");
        dot.push_str("    fillcolor=\"#f0f0f0\";\n\n");

        // Add nodes for this layer
        let layer_nodes: Vec<_> = nodes.iter()
            .filter(|n| n.formality_layer == l)
            .collect();

        for node in &layer_nodes {
            let short_id = &node.id[..8.min(node.id.len())];

            // Escape content for DOT format
            let content = node.content.replace("\"", "\\\"").replace("\n", "\\n");
            let truncated_content = if content.len() > 50 {
                format!("{}...", &content[..47])
            } else {
                content.clone()
            };

            // Color by kind
            let kind_str = node_kind_name(node.kind);
            let (kind_abbrev, color) = match kind_str {
                "constraint" => ("C", "#ffe0e0"),
                "assertion" => ("A", "#e0f0ff"),
                "scenario" => ("S", "#e0ffe0"),
                "definition" => ("D", "#fff0e0"),
                "domain" => ("Dom", "#f0e0ff"),
                _ => ("?", "#ffffff"),
            };

            let mut label = format!("[{}] {}\\n{}", kind_abbrev, short_id, truncated_content);

            // Optionally include metadata
            if include_metadata {
                if let Some(source) = node.metadata.get("source_file") {
                    label.push_str(&format!("\\nsrc: {}", source));
                }
                if let Some(inferred) = node.metadata.get("inferred") {
                    if inferred == "true" {
                        label.push_str("\\nauto-extracted");
                    }
                }
            }

            dot.push_str(&format!(
                "    \"{}\" [label=\"{}\", fillcolor=\"{}\", style=filled];\n",
                short_id, label, color
            ));
        }

        dot.push_str("  }\n\n");
    }

    // Add edges
    dot.push_str("  // Edges\n");
    for edge in &edges {
        let source_short = &edge.source_id[..8.min(edge.source_id.len())];
        let target_short = &edge.target_id[..8.min(edge.target_id.len())];

        // Skip if layer filter is set and neither source nor target matches
        if let Some(filter_layer) = layer {
            let source_node = nodes.iter().find(|n| n.id == edge.source_id);
            let target_node = nodes.iter().find(|n| n.id == edge.target_id);
            let source_in_layer = source_node.map(|n| n.formality_layer == filter_layer).unwrap_or(false);
            let target_in_layer = target_node.map(|n| n.formality_layer == filter_layer).unwrap_or(false);
            if !source_in_layer && !target_in_layer {
                continue;
            }
        }

        let edge_label = edge_kind_name(edge.kind);
        let (edge_style, edge_color) = match edge_label {
            "refines" => ("solid", "blue"),
            "depends_on" => ("dashed", "gray"),
            "contradicts" => ("bold", "red"),
            "derives_from" => ("dotted", "purple"),
            "synonym" => ("dashed", "green"),
            "formalizes" => ("bold", "darkblue"),
            "composes" => ("solid", "orange"),
            "transform" => ("bold", "darkorange"),
            _ => ("solid", "black"),
        };

        dot.push_str(&format!(
            "  \"{}\" -> \"{}\" [label=\"{}\", style=\"{}\", color=\"{}\"];\n",
            source_short, target_short, edge_label, edge_style, edge_color
        ));
    }

    dot.push_str("}\n");

    // Output to file or stdout
    if let Some(output_path) = output_file {
        std::fs::write(&output_path, &dot)?;
        println!("DOT file written to: {}", output_path);
        println!("\nVisualize with:");
        println!("  dot -Tpng {} -o spec-graph.png", output_path);
        println!("  dot -Tsvg {} -o spec-graph.svg", output_path);
    } else {
        println!("{}", dot);
    }

    Ok(())
}

/// Get human-readable name for formality layer
fn layer_name(layer: u32) -> &'static str {
    match layer {
        0 => "Natural Language Requirements",
        1 => "Formal Specifications",
        2 => "Interface Definitions",
        3 => "Implementation",
        _ => "Unknown Layer",
    }
}

